function placementInputs(){if(!currentPlacement)return;$('visualRotation').value=currentPlacement.angle;$('visualRotationValue').textContent=Math.round(currentPlacement.angle)+'°';for(const [key,id] of Object.entries(numeric))$(id).value=Math.round(currentPlacement[key]*10)/10;}
