async function restoreSurface(surface){artRevision++;artSignature='';restoring=true;activeSurface=surface;$('printSide').value=surface;engine.setSide(surface);const data=artByProduct[product.id]?.[surface];syncPrintAreaSize(engine.setPrintAreaSize(data?.areaSize||null));engine.setPrintAnchor(data?.anchor||null);updateAnchorStatus(data?.anchor||null);textStyle=sanitiseTextStyle(data?.textStyle);syncTextControls();artMode=data?.mode||'art';hasArt=data?.hasArt??false;$('designText').value=data?.text||'';$('ink').value=data?.ink||'#313e36';syncTextControls();$('scale').value=data?.scale||100;$('scaleValue').textContent=$('scale').value+'%';uploaded=null;if(data?.image){uploaded=await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=data.image})}currentPlacement={...(data?.placement||{x:0,y:0,w:spec.w,h:spec.h,angle:0})};$('artPanel').hidden=artMode!=='art';$('textPanel').hidden=artMode!=='text';$('artTab').classList.toggle('selected',artMode==='art');$('textTab').classList.toggle('selected',artMode==='text');$('artName').textContent=uploaded?'Your uploaded design':hasArt&&artMode==='text'?'Your text design':'No artwork on this surface';placementInputs();engine.place(currentPlacement);restoring=false;redraw();validatePlacement()}
