function renderOnMainThread(){if(!engine||!currentPlacement)return;$('scene').dataset.artworkRenderer='main';const p=currentPlacement;const aspect=p.h/p.w;const detail=artMode==='art'&&uploaded?Math.min(4096,Math.max(1024,uploaded.naturalWidth,uploaded.naturalHeight)):2048;canvas.width=aspect>1?Math.max(1,Math.round(detail/aspect)):detail;canvas.height=aspect>1?detail:Math.max(1,Math.round(detail*aspect));const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.clearRect(0,0,w,h);let overflow=false;if(hasArt){ctx.save();ctx.translate(w/2,h/2);const scale=+$('scale').value/100;ctx.scale(scale,scale);if(artMode==='text'){overflow=paintText(ctx,$('designText').value,textStyle,{width:w,height:h,frameWidthMm:p.w,color:$('ink').value}).overflow}else if(uploaded){const r=Math.min(w/uploaded.width,h/uploaded.height);ctx.drawImage(uploaded,-uploaded.width*r/2,-uploaded.height*r/2,uploaded.width*r,uploaded.height*r)}ctx.restore()}$('textLayoutStatus').textContent=overflow?'Text extends beyond the frame. Reduce its size or enlarge the frame.':'';engine.setArtwork(canvas);validatePlacement();snapshotSurface();mapEditor?.render()};
