$('capture').onclick=capture;save=()=>{gotoStep('share');capture()};
$('saveDesign').onclick=()=>{if(!currentPlacement||$('scene').getAttribute('aria-busy')==='true'){toast('Your merchandise is still loading.');return}snapshotSurface();const payload={schema:'pressroom-design-v1',product:product.id,color:color[1],surfaces:artByProduct[product.id],scene:sceneValues(),camera:engine.getState().camera,export:{ratio:$('exportRatio').value,width:$('exportSize').value,transparent:$('exportTransparent').checked}};downloadBlob(new Blob([JSON.stringify(payload)],{type:'application/json'}),'pressroom-'+product.id+'-design.json');toast('Editable design saved with its artwork')};
$('loadDesign').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>30*1024*1024)throw Error('File too large');const data=JSON.parse(await f.text());if(data.schema!=='pressroom-design-v1'||!products.some(p=>p.id===data.product)||!/^#[0-9a-f]{6}$/i.test(data.color))throw Error('Invalid design');for(const s of Object.values(data.surfaces||{})){if(!['art','text'].includes(s.mode)||typeof s.text!=='string'||s.text.length>1000||!/^#[0-9a-f]{6}$/i.test(s.ink)||s.image&&!/^data:image\/(png|jpeg);base64,/.test(s.image))throw Error('Invalid artwork');if(!Object.values(s.placement||{}).every(v=>typeof v==='number'&&Number.isFinite(v)&&Number.isFinite(v))||s.placement.w<=0||s.placement.h<=0)throw Error('Invalid placement')}
 snapshotSurface();product=products.find(p=>p.id===data.product);color=productPalette().find(c=>c[1]===data.color)||['Custom',data.color];artByProduct[product.id]=data.surfaces||{};currentModel=null;update();await rebuild();const ids={light:'lightPreset',intensity:'lightIntensity',azimuth:'lightAzimuth',elevation:'lightElevation',exposure:'exposure',background:'backgroundColor',backgroundMode:'backgroundMode'};for(const [key,id] of Object.entries(ids))if(data.scene?.[key]!==undefined)$(id).value=data.scene[key];$('groundShadow').checked=data.scene?.shadow??true;updateScene();if(data.export){$('exportRatio').value=String(data.export.ratio);$('exportSize').value=String(data.export.width);$('exportTransparent').checked=!!data.export.transparent}if(Array.isArray(data.camera?.position)&&data.camera.position.length===3&&data.camera.position.every(Number.isFinite)){const [x,y,z]=data.camera.position,r=Math.hypot(x,y,z);engine.restoreCamera(data.camera.position)}gotoStep('place');toast('Design restored')}catch(e){toast('This file is not a supported Pressroom design.')}finally{e.target.value=''}};
rebuild=async()=>{if(!engine)return;if(currentModel===product.id){engine.setColor(color[1]);return}currentModel=product.id;try{await engine.setProduct(product.id,color[1])}catch{currentModel=null;toast('The model could not load. Choose another product or reload.')}};
rotate=a=>engine?.view(a===Math.PI?'back':'front');zoom=d=>engine?.zoom(d);
async function initialize(){engine=await createStudio($('scene'),{onCamera:({azimuth,elevation})=>{$('cameraReadout').textContent=azimuth+'° / '+elevation+'°';$('cameraAzimuth').value=azimuth;$('cameraElevation').value=elevation;$('cameraAzimuthValue').textContent=azimuth+'°';$('cameraElevationValue').textContent=elevation+'°'},onModel:async info=>{spec=info.spec;$('printSide').options[0].textContent=spec.surfaceName||'Front';$('printSide').options[1].disabled=product.supportsBack===false;$('printSide').options[1].hidden=product.supportsBack===false;for(const [key,id] of Object.entries(numeric)){const max=key==='x'?spec.maxW/2:key==='y'?spec.maxH/2:key==='w'?spec.maxW:key==='h'?spec.maxH:180;if(key==='w'||key==='h')$(id).min=.1;else $(id).removeAttribute('min');$(id).removeAttribute('max')}$('printAreaInfo').textContent='Print guide: '+spec.maxW+' × '+spec.maxH+' mm. Check final placement with your printer before production.';currentPlacement=info.placement;await restoreSurface('front');if(product.supportsBack!==false&&artByProduct[product.id]?.back){await restoreSurface('back');await restoreSurface('front')}engine.setGuides(step==='place'&&$('printGuides').checked)},onPrintAnchor:anchor=>{updateAnchorStatus(anchor);snapshotSurface()},onError:message=>{$('placementStatus').textContent=message}});mapEditor=createSurfaceEditor($('printMap'),{read:()=>({spec,placement:currentPlacement,artCanvas:canvas,hasArtwork:hasArt,side:activeSurface,product}),onChange:p=>{if(p.w&&artMode==='text'){textStyle.size=Math.max(8,Math.min(120,textStyle.size*p.w/currentPlacement.w));syncTextControls()}place(p);redraw()},onFile:file,onFocus:()=>engine.focusDesign()});$('scene').ondragover=e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()};$('scene').ondrop=e=>{e.preventDefault();file(e.dataTransfer.files[0])};$('loading').remove();await rebuild();gotoStep('design');updateScene()}

function sanitiseTextStyle(value){const s={...TEXT_DEFAULTS,...value};s.font=['Arial','Georgia','Courier New','Verdana'].includes(s.font)?s.font:'Arial';s.size=Math.max(8,Math.min(120,Number(s.size)||32));s.align=['left','center','right','justify'].includes(s.align)?s.align:'center';s.lineHeight=Math.max(1,Math.min(2,Number(s.lineHeight)||1.25));return s}
function syncTextControls(){$('textFont').value=textStyle.font;$('textSize').value=textStyle.size;$('textLineHeight').value=textStyle.lineHeight;for(const key of ['bold','italic','underline']){const b=$('text'+key[0].toUpperCase()+key.slice(1));b.classList.toggle('selected',!!textStyle[key]);b.setAttribute('aria-pressed',!!textStyle[key])}document.querySelectorAll('[data-align]').forEach(b=>{b.classList.toggle('selected',b.dataset.align===textStyle.align);b.setAttribute('aria-pressed',b.dataset.align===textStyle.align)});$('textHex').value=$('ink').value}
for(const key of ['bold','italic','underline'])$('text'+key[0].toUpperCase()+key.slice(1)).onclick=()=>{textStyle[key]=!textStyle[key];syncTextControls();redraw()};
document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{textStyle.align=b.dataset.align;syncTextControls();redraw()});
$('textFont').onchange=()=>{textStyle.font=$('textFont').value;redraw()};$('textSize').oninput=()=>{textStyle.size=Math.max(8,Math.min(120,+$('textSize').value||32));redraw()};$('textLineHeight').onchange=()=>{textStyle.lineHeight=+$('textLineHeight').value;redraw()};$('ink').oninput=()=>{$('textHex').value=$('ink').value;redraw()};$('textHex').oninput=()=>{if(/^#[0-9a-f]{6}$/i.test($('textHex').value)){$('ink').value=$('textHex').value;redraw()}};$('textHex').onblur=()=>{$('textHex').value=$('ink').value};
let resizeOrigin=null;$('visualSize').onpointerdown=()=>{resizeOrigin={...currentPlacement}};$('visualSize').oninput=()=>{if(!currentPlacement)return;resizeOrigin??={...currentPlacement};const factor=+$('visualSize').value/100;const w=Math.max(.1,resizeOrigin.w*factor),h=Math.max(.1,resizeOrigin.h*factor);if(artMode==='text'){textStyle.size=Math.max(8,Math.min(120,textStyle.size*w/currentPlacement.w));syncTextControls()}place({w,h});redraw()};$('visualSize').onpointerup=()=>{resizeOrigin=null;$('visualSize').value=100};$('visualRotation').oninput=()=>place({angle:+$('visualRotation').value});$('zeroRotation').onclick=()=>place({angle:0});syncTextControls();
$('growArtwork').onclick=()=>{place({w:currentPlacement.w*1.25,h:currentPlacement.h*1.25});redraw()};$('shrinkArtwork').onclick=()=>{place({w:Math.max(.1,currentPlacement.w*.8),h:Math.max(.1,currentPlacement.h*.8)});redraw()};update();initialize().catch(e=>{$('loading').textContent='The studio could not load. Please reload to try again.';console.error(e)});



function updateAnchorStatus(anchor){$('printAnchorStatus').textContent=anchor?'Print area moved on the model. Saved with this surface.':'Print area at its default position.';$('moveAreaHelp').textContent=product.id==='mug'?'Drag the mug to move the wrap vertically. Use the flat map to position artwork around the handle-safe wrap.':'Enable this mode, then click or drag on the 3D model to place the print area. Turn it off to rotate the model.'}
$('movePrintArea').onchange=()=>{engine?.setMoveArea($('movePrintArea').checked);engine?.setGuides(true);$('printGuides').checked=true};
$('resetPrintArea').onclick=()=>{engine?.setPrintAnchor(null);updateAnchorStatus(null);snapshotSurface()};

function syncPrintAreaSize(size){spec={...product.print,maxW:size.w,maxH:size.h};$('printAreaWidth').value=Math.round(size.w*10)/10;$('printAreaHeight').value=Math.round(size.h*10)/10;$('printAreaWidth').max=product.id==='mug'?product.print.maxW:5000;$('printAreaHeight').max=product.id==='mug'?105:5000;$('printAreaHeight').disabled=product.print.shape==='circle';$('printAreaInfo').textContent='Print guide: '+Math.round(size.w)+' × '+Math.round(size.h)+' mm. The model clips artwork where there is no surface. Check final dimensions with your printer.';mapEditor?.render()}
for(const id of ['printAreaWidth','printAreaHeight'])$(id).oninput=()=>{if(!engine||!$(id).value)return;const w=+$('printAreaWidth').value,h=+$('printAreaHeight').value;if(!Number.isFinite(w)||!Number.isFinite(h)||w<=0||h<=0)return;syncPrintAreaSize(engine.setPrintAreaSize({w,h}));snapshotSurface();validatePlacement()};
$('resetPrintAreaSize').onclick=()=>{syncPrintAreaSize(engine.setPrintAreaSize(null));snapshotSurface();validatePlacement()};
